import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        long k = scanner.nextLong();

        if (k == 0) {
            System.out.println(factorial(n));
            return;
        }

        if (k > n - 1) {
            System.out.println(0);
            return;
        }

        int c = (int) (n - k);
        long answer = 0;

        for (int i = 1; i <= c; i++) {
            long sign = ((c - i) & 1) == 0 ? 1 : -1;
            long comb = nCr(c, i);
            long power = pow(i, n);
            answer += sign * comb * power;
        }

        answer = (answer * 2 * nCr(n, c)) % 998244353L;
        System.out.println(answer);
    }

    static long factorial(int n) {
        long res = 1;
        for (int i = 2; i <= n; i++) {
            res = (res * i) % 998244353L;
        }
        return res;
    }

    static long nCr(int n, int r) {
        if (r < 0 || r > n) return 0;
        long numerator = factorial(n);
        long denominator = (factorial(r) * factorial(n - r)) % 998244353L;
        return (numerator * modInverse(denominator, 998244353L)) % 998244353L;
    }

    static long pow(long base, int exp) {
        long result = 1;
        long b = base % 998244353L;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) result = (result * b) % 998244353L;
            b = (b * b) % 998244353L;
            e >>= 1;
        }
        return result;
    }

    static long modInverse(long a, long m) {
        long m0 = m, t, q;
        long x0 = 0, x1 = 1;
        if (m == 1) return 0;
        while (a > 1) {
            q = a / m;
            t = m;
            m = a % m; a = t;
            t = x0;
            x0 = x1 - q * x0;
            x1 = t;
        }
        if (x1 < 0) x1 += m0;
        return x1;
    }
}
